using matrix_pro::Matrix;
using matrix_pro::MemoryMode;

const std::size_t size = 512;

// 1) Cihaza ozel tamponlar: host aynasi yok
Matrix a(size, size, MemoryMode::device_only);
Matrix b(size, size, MemoryMode::device_only);
Matrix c(size, size, MemoryMode::device_only);

// 2) cuBLAS GEMM dongusu (kalici tamponlar)
for (int i = 0; i < 100; ++i) {
    c = multiply(a, b);
}

// 3) Fused / yerinde: tek cekirdek, tahsis yok
Matrix h = fused_bias_gelu(c, Matrix::zeros(1, size));
relu_(h);
add_scalar_(h, 0.5f);

// 4) Kopyasiz gorunum: transpose hic bellek dokunmadan
MatrixView t = transpose_view(h);

// 5) Asenkron argmax (pinned host yuvasi)
std::size_t* slot = static_cast<std::size_t*>(pin_host(sizeof(std::size_t)));
argmax_async(h, slot);
synchronize_pool();
unpin_host(slot);

using matrix_pro::Matrix;
using matrix_pro::Variable;

const std::size_t samples = 256, features = 64, hidden = 128, classes = 10;

// Agirliklarin host tarafi (SGD yerinde guncellenir)
Matrix w1_plain = Matrix::glorot(features, hidden);
Matrix b1_plain = Matrix::zeros(1, hidden);
Matrix w2_plain = Matrix::glorot(hidden, classes);
Matrix b2_plain = Matrix::zeros(1, classes);

Variable x(inputs, false);        // girdi: gradyan gerekmez
Variable y(targets, false);       // one-hot hedef

const float lr = 0.05f;
for (int step = 0; step < 60; ++step) {
    // 1) Parametreleri tape'e bagla
    Variable w1(w1_plain, true), b1(b1_plain, true);
    Variable w2(w2_plain, true), b2(b2_plain, true);

    // 2) Ileri gecis (tamami GPU'da)
    Variable h = x.matmul(w1).add(b1).relu();
    Variable z = h.matmul(w2).add(b2);
    Variable loss = softmax_cross_entropy_loss(z, y);   // fused

    // 3) Geri gecis: gradyanlar birikir
    loss.backward();

    // 4) SGD: gradyani oku ve yerinde uygula (tahsis yok)
    broadcast_add_(w1_plain, multiply(w1.grad(), -lr));
    broadcast_add_(b1_plain, multiply(b1.grad(), -lr));
    broadcast_add_(w2_plain, multiply(w2.grad(), -lr));
    broadcast_add_(b2_plain, multiply(b2.grad(), -lr));

    if (step % 10 == 0) {
        std::cout << "step " << step
                  << " loss " << mean(loss.value()) << '\n';
    }
}

