#include "matrix_pro/streams/stream_pool.hpp"

using matrix_pro::Matrix;

// Iki bagimsiz kol: iki farkli batch'in ileri+geri gecisi
Matrix a = Matrix::randn(2048, 512);
Matrix b = Matrix::randn(2048, 512);
Matrix w = Matrix::glorot(512, 512);
Matrix ga = Matrix::randn(512, 512);
Matrix gb = Matrix::randn(512, 512);

const float lr = 0.01f;

cudaEvent_t done_a = make_event();
cudaEvent_t done_b = make_event();

// Iki guncelleme ortusur: ayni anda cihazda
launch_on_pool(0, [&](cudaStream_t s) {
    (void)s;
    broadcast_add_(w, multiply(ga, -lr));
}, done_a);

launch_on_pool(1, [&](cudaStream_t s) {
    (void)s;
    Matrix w2 = w;                    // ikinci kol kendi kopyasinda calisir
    broadcast_add_(w2, multiply(gb, -lr));
}, done_b);

synchronize_pool();
destroy_event(done_a);
destroy_event(done_b);

Matrix logits = Matrix::randn(8192, 1000);

// Page-locked host slot: stream callback buraya yazar
std::size_t* slot = static_cast<std::size_t*>(pin_host(sizeof(std::size_t)));

argmax_async(logits, slot, [](std::size_t idx) {
    // Deger hazir oldugunda cagrilir; cagiran thread bloke edilmedi
    std::cout << "predicted class: " << idx << '\n';
});

// Buradaki is devam eder: pipeline beklemez
Matrix probs = softmax(logits);

synchronize_pool();
unpin_host(slot);

#include <iostream>
#include "matrix_pro/matrix_pro.hpp"

int main() {
    using namespace matrix_pro;

    Matrix x = Matrix::randn(1024, 1024);
    Matrix w = Matrix::glorot(1024, 1024);
    Matrix b = Matrix::zeros(1, 1024);
    Matrix out(1024, 1024);

    // Warm-up run
    out = (x * w).add_row_vector(b).relu();
    out.synchronize();

    // Capture kernel sequence into CUDA Graph
    CudaGraph graph;
    graph.begin_capture();
    out = (x * w).add_row_vector(b).relu();
    graph.end_capture();

    // Replay 10,000 times at hardware speed with zero CPU overhead
    for (int i = 0; i < 10000; ++i) {
        graph.replay();
    }
    synchronize();
    std::cout << "10,000 iterations completed via CUDA Graph!\n";
    return 0;
}

#include <iostream>
#include "matrix_pro/matrix_pro.hpp"

int main() {
    using namespace matrix_pro;

    // Build model state dict
    Checkpoint ckpt;
    ckpt.add("fc1.weight", Matrix::glorot(784, 256));
    ckpt.add("fc1.bias", Matrix::zeros(1, 256));
    ckpt.add("fc2.weight", Matrix::glorot(256, 10));
    ckpt.add("input_cache", Tensor({32, 1, 28, 28}));

    ckpt.set_metadata("epoch", "100");
    ckpt.set_metadata("val_loss", "0.0142");
    ckpt.set_metadata("optimizer", "adamw");

    // Save to disk at NVMe wire speed
    ckpt.save("model_checkpoint.mfc");
    std::cout << "Saved " << ckpt.size() << " tensors to model_checkpoint.mfc\n";

    // Load back on another machine/run
    Checkpoint restored = Checkpoint::load("model_checkpoint.mfc");
    Matrix fc1_w = restored.get_matrix("fc1.weight");
    std::cout << "Restored fc1.weight (" << fc1_w.rows() << "x" << fc1_w.cols() << ")\n";
    std::cout << "Epoch: " << restored.get_metadata("epoch") << "\n";
    return 0;
}
